function rotationDroite(tab, k) {
    if (tab.length === 0 || k < 0) {
        return tab.slice();
    }
    const n = tab.length;
    k = k % n;
    let resultat = [];
    for (let i = n - k; i < n; i++) {
        resultat.push(tab[i]);
    }
    for (let i = 0; i < n - k; i++) {
        resultat.push(tab[i]);
    }
    return resultat;
}
